from pathlib import Path
p=Path('scripts/lab_t164_clock_price_alignment.py')
s=p.read_text()
s=s.replace('from dataclasses import dataclass','from dataclasses import asdict, dataclass')
s=s.replace('def _permutation_p_value(\n', 'def _per_entry_best_shifts(\n    owners: Sequence[OwnerEntry], minutes: Sequence[Candle], alignment: Alignment\n) -> list[dict[str, object]]:\n    by_minute = {bar.ts_utc.replace(second=0, microsecond=0): bar for bar in minutes}\n    rows: list[dict[str, object]] = []\n    for owner in owners:\n        candidates: list[tuple[float, int, float, float]] = []\n        for shift in SHIFT_MINUTES:\n            bar = _bar_for_shift(by_minute, owner.entry_time, shift)\n            if bar is None:\n                continue\n            value = _basis(bar, alignment.basis)\n            residual = abs(owner.entry_price - value - alignment.basis_offset)\n            candidates.append((residual, shift, value, owner.entry_price - value))\n        if candidates:\n            residual, shift, value, raw = min(candidates)\n            rows.append({\n                "direction": owner.direction,\n                "owner_time_ny": owner.entry_time.astimezone(OWNER_ZONE).isoformat(),\n                "owner_time_utc": owner.entry_time.isoformat(),\n                "owner_price": owner.entry_price,\n                "best_shift_minutes": shift,\n                "residual_after_basis": residual,\n                "raw_basis_difference": raw,\n                "recorded_value": value,\n            })\n    return rows\n\n\ndef _permutation_p_value(\n')
# Remove per_entry accumulation from scan, retaining empty placeholders for compatibility.
start='    for name in BASIS_NAMES:\n        for shift in SHIFT_MINUTES:'
s=s.replace(start, '    for name in BASIS_NAMES:\n        for shift in SHIFT_MINUTES:', 1)
# Remove block that appends raw per entry (exact text)
old='''        for owner in owners:\n            candidates: list[tuple[float, int, float, float]] = []\n            for shift in SHIFT_MINUTES:\n                bar = _bar_for_shift(by_minute, owner.entry_time, shift)\n                if bar is None:\n                    continue\n                raw = owner.entry_price - _basis(bar, name)\n                candidates.append((abs(raw - 0.0), shift, raw, _basis(bar, name)))\n            if candidates:\n                _, shift, raw, value = min(candidates)\n                per_entry[name].append(\n                    {\n                        "direction": owner.direction,\n                        "owner_time_ny": owner.entry_time.astimezone(OWNER_ZONE).isoformat(),\n                        "owner_time_utc": owner.entry_time.isoformat(),\n                        "owner_price": owner.entry_price,\n                        "best_shift_minutes": shift,\n                        "raw_basis_difference": raw,\n                        "recorded_value": value,\n                    }\n                )\n'''
s=s.replace(old,'')
s=s.replace('    return results, per_entry\n','    return results, per_entry\n')
s=s.replace('    alignments, per_entry = scan_alignments(owners, minutes)\n    best = min(alignments, key=lambda item: item.median_abs_residual)\n', '    alignments, _ = scan_alignments(owners, minutes)\n    best = min(alignments, key=lambda item: item.median_abs_residual)\n    per_entry = {best.basis: _per_entry_best_shifts(owners, minutes, best)}\n')
s=s.replace('"alignment_results": [item.__dict__ for item in alignments],','"alignment_results": [asdict(item) for item in alignments],')
s=s.replace('"shift_grid_minutes": [-360, 360],','"shift_grid": {"minimum": -360, "maximum": 360, "step": 1},')
p.write_text(s)
